const evernoteChooser=document.getElementById("evernote-chooser");
document.addEventListener("click",event=>{
  const card=event.target.closest?.('a.destination-card[href="evernote:///"]');
  if(card && evernoteChooser){event.preventDefault();evernoteChooser.showModal();}
});
evernoteChooser?.addEventListener("click",event=>{
  if(event.target===evernoteChooser || event.target.closest("[data-close-evernote]"))evernoteChooser.close();
});
